// Per column frame: whether Chzzk's follow, subscribe and gift-subscription buttons are on screen and on top
// (the frame CSS once hid <main>'s whole channel row) and the player box ratio (must stay 16:9). The row must start at the
// player's bottom (gap 0, it once floated mid-frame in wide frames), show no name or follower count (the column
// header carries them, as stat), and end its buttons at its right padding (right: row right - last button right).
(() => {
  const box = (e) => (e ? [e.getBoundingClientRect()].map((r) => [r.x, r.y, r.width, r.height].map(Math.round))[0] : null);
  return JSON.stringify([...document.querySelectorAll(".cb-split-body > iframe")].map((f) => {
    const d = f.contentDocument, w = f.contentWindow;
    const hit = (re) => {
      const b = [...d.querySelectorAll("#layout-body main button")].find((b) => re.test(b.innerText));
      if (!b) return "missing";
      const r = b.getBoundingClientRect(), e = d.elementFromPoint(r.x + r.width / 2, r.y + r.height / 2);
      return r.width > 0 && r.top >= 0 && r.bottom <= w.innerHeight && r.left >= 0 && r.right <= w.innerWidth && !!e && b.contains(e);
    };
    const pe = d.querySelector("#layout-body main > :first-child > :first-child"), p = box(pe);
    const row = d.querySelector('#layout-body main > [class*="_details_"]'), shown = [...(row?.querySelectorAll("button") ?? [])].filter((b) => b.getBoundingClientRect().width > 0);
    const name = row?.querySelector('[class*="_channel_"]');
    return {
      col: f.dataset.cbCol.slice(0, 8), frame: [w.innerWidth, w.innerHeight], player: p, ratio: p && +(p[2] / p[3]).toFixed(2),
      details: box(row), aside: box(d.querySelector("#aside-chatting")), pad: row && getComputedStyle(row).padding,
      gap: row && pe && Math.round(row.getBoundingClientRect().top - pe.getBoundingClientRect().bottom),
      right: row && shown.length ? Math.round(row.getBoundingClientRect().right - Math.max(...shown.map((b) => b.getBoundingClientRect().right))) : null,
      nameHidden: !name || name.getBoundingClientRect().width === 0,
      stat: f.closest(".cb-split-col")?.querySelector(".cb-split-stat")?.textContent ?? null,
      follow: hit(/^팔로우|^팔로잉|^언팔로우/), subscribe: hit(/^구독$|^구독 중|^구독하기/), gift: hit(/구독 선물/),
    };
  }));
})()

